function Limb({ a, b, radius = .2, color = SILVER }: { a: number[]; b: number[]; radius?: number; color?: string }) {
  const { midpoint, quaternion, length } = useMemo(() => { const from = new THREE.Vector3(...a); const to = new THREE.Vector3(...b); const direction = to.clone().sub(from); return { midpoint: from.add(to).multiplyScalar(.5), quaternion: new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), direction.clone().normalize()), length: direction.length() }; }, [a, b]);
  return <mesh position={midpoint} quaternion={quaternion} castShadow><capsuleGeometry args={[radius, Math.max(.01, length - radius * 2), 5, 12]} /><meshStandardMaterial color={color} metalness={.6} roughness={.31} /></mesh>;
}

