export function AvatarPreview({seed,accent,traits,reducedMotion}:{seed:number;accent:string;traits?:AppearanceTraits;reducedMotion?:boolean}){const{visible,reduced}=useScenePreferences();return <SceneBoundary><Canvas orthographic frameloop={visible?"always":"never"} dpr={[1,1.5]} camera={{manual:true,position:[1.65,.65,4],zoom:80,near:.1,far:100}} style={{background:"transparent",width:"100%",height:"100%"}}><ambientLight intensity={1.6} color="#c7d4d9"/><directionalLight position={[-3,5,3]} intensity={3.5} color="#ffdfaf"/><directionalLight position={[3,2,-2]} intensity={2.5} color="#d4d0c8"/><PreviewFigure seed={seed} accent={accent} traits={traits} reducedMotion={reducedMotion??reduced}/></Canvas></SceneBoundary>}
